def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    comps = components((g != bg) & (g != 2), diagonal=False)
    bodies = [set(map(tuple, c)) for c in comps]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    markers = [set() for c in comps]
    for y, x in map(tuple, np.argwhere(g == 2)):
        distances = [min(abs(y - a) + abs(x - b) for a, b in body) for body in bodies]
        owners = [i for i, d in enumerate(distances) if d == min(distances)]
        if len(owners) != 1:
            raise ValueError('Ambiguous connector ownership')
        markers[owners[0]].add((y, x))
    normals = []
    for body, marks in zip(bodies, markers):
        normals.append({p: {(dy, dx) for dy, dx in directions if (p[0] + dy, p[1] + dx) in body} for p in marks})
    anchors = [i for i, b in enumerate(bodies) if all(g[p] == 4 for p in b)]
    anchor = max(anchors, key=lambda i: len(bodies[i]))
    failed = set()

    def search(remaining, occupied, opened, closed, placements):
        state = tuple(sorted(placements))
        if state in failed:
            return None
        if not remaining:
            return placements if not opened else None
        candidates = []
        for i in sorted(remaining):
            shifts = {(oy - my, ox - mx) for my, mx in markers[i] for oy, ox in opened}
            for dy, dx in sorted(shifts):
                body = {(y + dy, x + dx) for y, x in bodies[i]}
                marks = {(y + dy, x + dx): normals[i][(y, x)] for y, x in markers[i]}
                if any(not (0 <= y < H and 0 <= x < W) for y, x in body | set(marks)):
                    continue
                if body & (occupied | set(opened) | closed):
                    continue
                if set(marks) & (occupied | closed):
                    continue
                matched = set(marks) & set(opened)
                if not matched:
                    continue
                candidates.append((-len(matched), i, dy, dx, body, marks, matched))
        for _, i, dy, dx, body, marks, matched in sorted(candidates, key=lambda c: c[:4]):
            next_open = {p: n for p, n in opened.items() if p not in matched}
            next_open.update({p: n for p, n in marks.items() if p not in matched})
            result = search(remaining - {i}, occupied | body, next_open, closed | matched,
                            placements + [(i, dy, dx)])
            if result is not None:
                return result
        failed.add(state)
        return None

    placements = search(set(range(len(bodies))) - {anchor}, bodies[anchor], normals[anchor],
                        set(), [(anchor, 0, 0)])
    if placements is None:
        raise ValueError('No complete connector assembly')
    out = np.full_like(g, bg)
    for i, dy, dx in placements:
        for y, x in bodies[i]:
            out[y + dy, x + dx] = g[y, x]
        for y, x in markers[i]:
            out[y + dy, x + dx] = 2
        emit(out, 'Keep the yellow anchor fixed.' if i == anchor else
             'Translate this whole piece to align matching red connectors; preserve its orientation and colour.')
    return out
